// Everything a plugin sends a model comes from its Fluent catalog: only a Catalog can make
// ModelText. Strict where Fluent would print a placeholder, and pure, so it runs in a Claude Code
// mod too.
import { FluentBundle, FluentNumber, FluentResource } from "./vendor/fluent/index.js";

const MINT: unique symbol = Symbol("model text");

/**
 * Text for the model. Its brand keeps any other object with a `text` from passing as one, while
 * every plugin's copy of the kit, and the tools that read them all, agree on the type; the build
 * refuses the brand written anywhere but here (tools/build/purity.ts).
 */
export class ModelText {
	readonly text: string;
	readonly brand = "piebird-catalog";
	constructor(mint: typeof MINT, text: string) {
		if (mint !== MINT) throw new Error("ModelText comes from a Catalog");
		this.text = text;
	}
	toString(): string {
		return this.text;
	}
}

/**
 * Texts from the catalog one after another, each on its own line, or with an empty line between
 * them as paragraphs. Line breaks are the one thing code adds: words come from the catalog.
 */
export function joinText(parts: readonly ModelText[], between: "line" | "paragraph" = "line"): ModelText {
	return new ModelText(MINT, parts.map(p => p.text).join(between === "line" ? "\n" : "\n\n"));
}

/** The message ids formatted while a trace runs, for the "what the model sees" page. */
let traced: string[] | undefined;

/** Runs `run` and returns, with its value, the ids of the messages it formatted, in order, each once. */
export async function traceMessages<T>(run: () => Promise<T>): Promise<{ value: T; ids: string[] }> {
	const outer = traced;
	traced = [];
	try {
		const value = await run();
		return { value, ids: [...new Set(traced)] };
	} finally {
		traced = outer;
	}
}

export type Variables = Readonly<Record<string, string | number>>;

/** Numbers as written, not grouped the locale's way: a line number reads as a call takes it. */
function plain(variables: Variables | undefined): Record<string, string | FluentNumber> | undefined {
	if (variables === undefined) return undefined;
	return Object.fromEntries(
		Object.entries(variables).map(([k, v]) => [
			k,
			typeof v === "number" ? new FluentNumber(v, { useGrouping: false }) : v,
		]),
	);
}

type Args<M, K extends keyof M> = M[K] extends undefined ? [] : [variables: M[K]];

/** `M` maps each message id, and `id.attribute`, to its variables, or `undefined` when it takes none. */
export class Catalog<M extends Record<string, Variables | undefined>> {
	readonly #bundle: FluentBundle;

	constructor(source: string) {
		// Bidi isolation marks around placeables would reach the model as text.
		this.#bundle = new FluentBundle("en-US", { useIsolating: false });
		// The parser skips an entry it can't read; the build refuses those (tools/build/model.ts).
		const errors = this.#bundle.addResource(new FluentResource(source));
		if (errors.length > 0) throw new Error(`the catalog: ${errors.map(e => e.message).join("; ")}`);
	}

	text<K extends keyof M & string>(id: K, ...args: Args<M, K>): ModelText {
		return this.#format(id, args[0]);
	}

	/**
	 * The message `id` chosen at run time, such as a vault's declared error. It throws, as `text`
	 * does, when the catalog lacks the message or `variables` lacks one it needs.
	 */
	textById(id: string, variables?: Variables): ModelText {
		return this.#format(id, variables);
	}

	#format(id: string, variables: Variables | undefined): ModelText {
		const [name, attribute] = id.split(".", 2);
		const message = this.#bundle.getMessage(name);
		if (!message) throw new Error(`no message ${name} in the catalog`);
		const pattern = attribute === undefined ? message.value : message.attributes[attribute];
		if (!pattern) throw new Error(`message ${id} has no ${attribute === undefined ? "value" : "such attribute"}`);
		const errors: Error[] = [];
		const text = this.#bundle.formatPattern(pattern, plain(variables), errors);
		if (errors.length > 0) throw new Error(`message ${id}: ${errors.map(e => e.message).join("; ")}`);
		traced?.push(id);
		return new ModelText(MINT, text);
	}
}

files.../core/folder.ts:
// Where a project keeps its threads: the folder the plugin's "folder" setting names
// (core/settings.json), else the one the nearest .omp/threads.json names, as
// `{"folder": "<path>"}`, from the project's folder up. Nothing is guessed: without either, a
// project has no threads list. A relative path is relative to where it was written: the person's
// settings file to the home folder, the project's file and an agent's own screen to the project,
// .omp/threads.json to the folder holding .omp/. The folder may lie outside the project (a sibling
// notes repository, an absolute path): a project's settings are trusted as much as its code.
import type { Io, Place } from "../kit/core/io";
import type { ModelText } from "../kit/core/model";
import type { AgentChoice } from "../kit/core/settings";
import { agentChoices, readSettings } from "../kit/core/settings";
import { model } from "./model.gen";
import { declared } from "./settings.gen";

export const PLUGIN = "piebird-threads";

/** A project's threads folder: its absolute path, and its name as the project gives it. */
export interface ThreadsFolder {
	readonly path: string;
	readonly name: string;
}

/** A failure the model is told about, in the catalog's words. */
export class ThreadsError extends Error {
	constructor(readonly said: ModelText) {
		super(said.text);
	}
}

function isAbsolute(path: string): boolean {
	return path.startsWith("/") || path.startsWith("\\\\") || /^[A-Za-z]:[\\/]/.test(path);
}

/** A Windows network share's root, `\\server\share` (either separator), written `//server/share`. */
const SHARE = /^[\\/]{2}([^\\/]+)[\\/]+([^\\/]+)/;

/**
 * A path's root and the parts after it: the root is empty for `/`, a drive (`C:`), or a network
 * share (`//server/share`), which `..` never leaves.
 */
function rooted(whole: string): { root: string; parts: string[] } {
	const share = SHARE.exec(whole);
	if (share) return { root: `//${share[1]}/${share[2]}`, parts: whole.slice(share[0].length).split(/[\\/]/) };
	const [root = "", ...parts] = whole.split(/[\\/]/);
	return { root, parts };
}

/** `path` taken from `base` when relative, its `.` and `..` resolved; separators become `/`. */
export function resolvePath(base: string, path: string): string {
	const { root, parts } = rooted(isAbsolute(path) ? path : `${base}/${path}`);
	const kept: string[] = [];
	for (const part of parts) {
		if (part === "" || part === ".") continue;
		if (part === "..") kept.pop();
		else kept.push(part);
	}
	return `${root}/${kept.join("/")}`;
}

/** The folder holding `dir`, or `dir` itself at the root (`/`, a drive's or a network share's). */
function parentOf(dir: string): string {
	const share = SHARE.exec(dir);
	if (share && /^[\\/]*$/.test(dir.slice(share[0].length))) return dir;
	const at = Math.max(dir.lastIndexOf("/"), dir.lastIndexOf("\\"));
	if (at < 0) return dir;
	return at === 0 ? "/" : dir.slice(0, at);
}

/** A folder as the project wrote it, without trailing separators. */
function trimmed(name: string): string {
	return name.trim().replace(/[\\/]+$/, "");
}

/** The folder the nearest .omp/threads.json names from `dir` up; one that names none throws. */
async function fromOmpFile(io: Io, dir: string): Promise<ThreadsFolder | undefined> {
	for (let at = dir; ; at = parentOf(at)) {
		const config = resolvePath(at, ".omp/threads.json");
		const text = await io.readText(config);
		if (text !== undefined) {
			const parsed: unknown = JSON.parse(text);
			const folder = typeof parsed === "object" && parsed !== null && "folder" in parsed ? parsed.folder : undefined;
			if (typeof folder !== "string" || trimmed(folder) === "")
				throw new ThreadsError(model.text("reason-no-folder", { config }));
			return { path: resolvePath(at, trimmed(folder)), name: trimmed(folder) };
		}
		if (parentOf(at) === at) return undefined;
	}
}

/** The project's threads folder at `place`, given the agent's own choices, or undefined when none is named. */
export async function threadsFolder(io: Io, place: Place, choice?: AgentChoice): Promise<ThreadsFolder | undefined> {
	const { values } = await readSettings(io, place, { plugin: PLUGIN, declared, ...agentChoices("folder", choice) });
	const setting = values.folder;
	if (setting === undefined || trimmed(setting.value) === "") return fromOmpFile(io, place.project);
	const base = setting.from === "user" ? place.home : place.project;
	const name = trimmed(setting.value);
	return { path: resolvePath(base, name), name };
}

files.../core/update.ts:
// What the main agent is told about the project's threads, and when: the list when it differs from
// the last one the agent got; once every thread is closed or dormant, a line saying there are none;
// once nothing names a threads folder any more, a line saying earlier lists no longer apply. An
// agent with no rules of its own gets the plugin's rule with the list.
import type { Io, Place } from "../kit/core/io";
import type { ModelText } from "../kit/core/model";
import type { AgentChoice } from "../kit/core/settings";
import { parseRule } from "../kit/core/rules";
import { threadsFolder } from "./folder";
import { threadsList } from "./list";
import { model } from "./model.gen";

/**
 * What to tell the agent now, given the last text it got (undefined for none since the start or
 * the last compaction), or undefined when that still holds. `now` is seconds since the epoch.
 */
export async function threadsUpdate(
	io: Io,
	place: Place,
	at: { readonly choice?: AgentChoice; readonly last: unknown; readonly now: number },
): Promise<ModelText | undefined> {
	const folder = await threadsFolder(io, place, at.choice);
	if (folder === undefined) {
		// A list sent earlier must not stay the latest word once nothing names its folder.
		const gone = model.text("no-folder");
		return at.last === undefined || at.last === gone.text ? undefined : gone;
	}
	// A list sent earlier must not stay the latest word once every thread is closed or dormant.
	const text =
		(await threadsList(io, folder, at.now)) ??
		(at.last === undefined ? undefined : model.text("none", { folder: folder.name }));
	return text === undefined || text.text === at.last ? undefined : text;
}

/** A rule file's body, as omp gives an always-applied rule: front matter left out. */
export function ruleText(markdown: string): ModelText {
	return model.text("rule", { body: parseRule("threads", markdown).body });
}

files.../kit/core/operations.ts:
// A plugin's operations (core/operations.json) joined with their text from core/model.ftl, as its
// generated core/operations.gen.ts carries them, and the contract between the shells and the code
// that performs an operation. The build has checked the file and the text (tools/build/operations.ts);
// this reads them into types and refuses what the code can't use.
import type { ModelText } from "./model";

export type JsonSchema = Readonly<Record<string, unknown>>;

/** MCP's tool annotations, and whether the tool stays in front of tool search. */
export interface ToolHints {
	readonly readOnly?: boolean;
	readonly destructive?: boolean;
	readonly idempotent?: boolean;
	readonly openWorld?: boolean;
	readonly alwaysLoad?: boolean;
	/** It runs code the model wrote. */
	readonly runsCode?: boolean;
}

export interface Tool {
	readonly name: string;
	readonly description: ModelText;
	/** The operation's input with each argument's description, from model.ftl, filled in. */
	readonly inputSchema: JsonSchema;
	readonly outputSchema: JsonSchema;
	readonly hints: ToolHints;
}

export interface Operation {
	readonly id: string;
	readonly input: JsonSchema;
	readonly output: JsonSchema;
	readonly errors: readonly string[];
	/** The plugin's vault performs it: it needs a secret. */
	readonly vault: boolean;
	readonly tool?: Tool;
}

/** What an operation ends with: its answer, as the model reads it and as data, or a declared error. */
export type Outcome =
	| { readonly ok: true; readonly text: ModelText; readonly data: unknown }
	| { readonly ok: false; readonly error: string; readonly text: ModelText };

/**
 * A call's cancellation as core sees it: the platform's AbortSignal, which aborts when the caller
 * cancels the call. Core names only what it reads, so it typechecks where there's no AbortSignal
 * type (a Claude Code mod); a shell that hands it to its platform checks it is one.
 */
export interface CallSignal {
	readonly aborted: boolean;
}

/**
 * Performs one operation; the input is as the caller sent it, for the handler to check. `signal`
 * aborts when the caller cancels the call: whatever the handler started (a program, a wait) stops.
 */
export type Handler = (input: unknown, signal?: CallSignal) => Promise<Outcome>;

export type Handlers = Readonly<Record<string, Handler>>;

/**
 * What the model reads when a tool can't answer as its operation says, from the plugin's catalog:
 * `crashed`, error-crashed, when its code fails instead (a bug, an unexpected error), with the
 * failure's own message; `badArguments`, error-arguments, when the arguments don't fit the tool's
 * input schema, with what doesn't. A plugin with tools has both (tools/build/operations.ts).
 */
export interface ToolWords {
	readonly crashed: (cause: string) => ModelText;
	readonly badArguments: (problem: string) => ModelText;
}

export interface Operations extends ToolWords {
	readonly byId: ReadonlyMap<string, Operation>;
	/** The operations the model gets as tools, in declaration order. */
	readonly tools: readonly (Operation & { readonly tool: Tool })[];
}

/** The failure `error` as the model reads it: the catalog's error-crashed with its message. */
export function crashText(operations: Operations, error: unknown): ModelText {
	return operations.crashed(error instanceof Error ? error.message : String(error));
}

/** For a plugin without tools: it never needs these words. */
const NO_TOOLS: ToolWords = {
	crashed: () => {
		throw new Error("this plugin has no tools");
	},
	badArguments: () => {
		throw new Error("this plugin has no tools");
	},
};

type Fields = Readonly<Record<string, unknown>>;

function isFields(value: unknown): value is Fields {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function fields(value: unknown, at: string): Fields {
	if (isFields(value)) return value;
	throw new Error(`operations.json: ${at} isn't an object`);
}

function textFor(text: ReadonlyMap<string, ModelText>, id: string): ModelText {
	const found = text.get(id);
	if (found === undefined) throw new Error(`model.ftl: no ${id}`);
	return found;
}

function hints(tool: Fields): ToolHints {
	const flag = (k: string) => (typeof tool[k] === "boolean" ? { [k]: tool[k] } : {});
	return {
		...flag("readOnly"),
		...flag("destructive"),
		...flag("idempotent"),
		...flag("openWorld"),
		...flag("alwaysLoad"),
		...flag("runsCode"),
	};
}

function toolFor(id: string, op: Fields, text: ReadonlyMap<string, ModelText>): Tool | undefined {
	if (op.tool === undefined) return undefined;
	const tool = fields(op.tool, `/operations/${id}/tool`);
	if (typeof tool.name !== "string") throw new Error(`operations.json: /operations/${id}/tool/name isn't text`);
	const input = fields(op.input, `/operations/${id}/input`);
	const props = fields(input.properties ?? {}, `/operations/${id}/input/properties`);
	const described = Object.fromEntries(
		Object.entries(props).map(([arg, schema]) => [
			arg,
			{
				...fields(schema, `/operations/${id}/input/properties/${arg}`),
				description: textFor(text, `${id}.${arg}`).text,
			},
		]),
	);
	return {
		name: tool.name,
		description: textFor(text, id),
		inputSchema: { ...input, properties: described },
		outputSchema: fields(op.output, `/operations/${id}/output`),
		hints: hints(tool),
	};
}

/**
 * The operations in `source` (operations.json without `$schema`), each tool given its text, with
 * `words` for a tool that can't answer; a plugin without tools needs none.
 */
export function parseOperations(
	source: string,
	text: ReadonlyMap<string, ModelText>,
	words: ToolWords = NO_TOOLS,
): Operations {
	const parsed: unknown = JSON.parse(source);
	const byId = new Map<string, Operation>();
	for (const [id, value] of Object.entries(fields(fields(parsed, "").operations, "/operations"))) {
		const op = fields(value, `/operations/${id}`);
		const errors = Array.isArray(op.errors) ? op.errors.filter((e): e is string => typeof e === "string") : [];
		const tool = toolFor(id, op, text);
		const base = {
			id,
			input: fields(op.input, `/operations/${id}/input`),
			output: fields(op.output, `/operations/${id}/output`),
			errors,
			vault: op.vault === true,
		};
		byId.set(id, tool === undefined ? base : { ...base, tool });
	}
	const tools = [...byId.values()].flatMap(op => (op.tool === undefined ? [] : [{ ...op, tool: op.tool }]));
	return { byId, tools, ...words };
}

